import sys

def solve():
    # Increase recursion depth to handle deep trees (up to 2*10^5)
    sys.setrecursionlimit(300000)

    # Read all input at once for speed
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    # Build adjacency list
    adj = [[] for _ in range(N)]
    for _ in range(N - 1):
        try:
            u = int(next(iterator)) - 1
            v = int(next(iterator)) - 1
        except StopIteration:
            break
        adj[u].append(v)
        adj[v].append(u)

    # dp[u][0]: Size of best alkane rooted at u where u is a leaf (deg 1)
    # dp[u][1]: Size of best alkane rooted at u where u is a branch (deg 4) connected to parent
    # dp[u][2]: Size of best alkane rooted at u where u is the root (deg 4) not connected to parent
    dp = [[0, 0, 0] for _ in range(N)]

    visited = [False] * N

    # Iterative DFS to avoid recursion limits issues even if set high
    stack = [(0, False)] # (node, processed_children_flag)

    while stack:
        u, processed = stack.pop()

        if not processed:
            visited[u] = True
            stack.append((u, True))

            # Push children
            for v in adj[u]:
                if not visited[v]:
                    stack.append((v, False))
        else:
            # Post-order processing: children are already processed

            # Collect potential gains from children
            child_vals = []
            for v in adj[u]:
                if visited[v]:
                    # If we include v, it must be a leaf or a branch relative to u
                    # dp[v][2] corresponds to v being a root, which disconnects from u, so we ignore it here.
                    gain = max(dp[v][0], dp[v][1])
                    child_vals.append(gain)

            # Sort descending to pick the best ones
            child_vals.sort(reverse=True)

            # Case 0: u is a leaf. No children needed.
            dp[u][0] = 1

            # Case 1: u is a branch (connected to parent). Needs 3 children.
            s1 = 1
            for i in range(min(3, len(child_vals))):
                if child_vals[i] > 0:
                    s1 += child_vals[i]
                else:
                    break
            dp[u][1] = s1

            # Case 2: u is the root. Needs 4 children.
            s2 = 1
            for i in range(min(4, len(child_vals))):
                if child_vals[i] > 0:
                    s2 += child_vals[i]
                else:
                    break
            dp[u][2] = s2

    # The answer is the best structure rooted at some node acting as degree 4 root.
    ans = 0
    for i in range(N):
        if dp[i][2] > ans:
            ans = dp[i][2]

    if ans == 0:
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    solve()
